class Solution {
    int memo[105][105][25];
    int M, N;
    int dp(int i, int t, int prevC, const std::vector<int>& houses, const std::vector<std::vector<int>>& cost) {
        if (t < 0) return 1e9;
        if (i == M) return t == 0 ? 0 : 1e9;
        if (memo[i][t][prevC] != -1) return memo[i][t][prevC];
        if (houses[i] != 0) {
            int c = houses[i];
            return memo[i][t][prevC] = dp(i + 1, t - (c != prevC ? 1 : 0), c, houses, cost);
        }
        int ans = 1e9;
        for (int c = 1; c <= N; ++c) {
            ans = std::min(ans, cost[i][c - 1] + dp(i + 1, t - (c != prevC ? 1 : 0), c, houses, cost));
        }
        return memo[i][t][prevC] = ans;
    }
public:
    int minCost(std::vector<int>& houses, std::vector<std::vector<int>>& cost, int m, int n, int target) {
        M = m; N = n;
        std::memset(memo, -1, sizeof(memo));
        int res = dp(0, target, 0, houses, cost);
        return res >= 1e9 ? -1 : res;
    }
};

import java.util.*;

class Solution {
    private int[][][] memo;
    private int M, N;
    private int dp(int i, int t, int prevC, int[] houses, int[][] cost) {
        if (t < 0) return 1000000000;
        if (i == M) return t == 0 ? 0 : 1000000000;
        if (memo[i][t][prevC] != -1) return memo[i][t][prevC];
        if (houses[i] != 0) {
            int c = houses[i];
            return memo[i][t][prevC] = dp(i + 1, t - (c != prevC ? 1 : 0), c, houses, cost);
        }
        int ans = 1000000000;
        for (int c = 1; c <= N; c++) {
            ans = Math.min(ans, cost[i][c - 1] + dp(i + 1, t - (c != prevC ? 1 : 0), c, houses, cost));
        }
        return memo[i][t][prevC] = ans;
    }
    public int minCost(int[] houses, int[][] cost, int m, int n, int target) {
        M = m; N = n;
        memo = new int[m + 1][target + 1][n + 1];
        for (int[][] mat : memo) for (int[] row : mat) Arrays.fill(row, -1);
        int res = dp(0, target, 0, houses, cost);
        return res >= 1000000000 ? -1 : res;
    }
}

var minCost = function(houses, cost, m, n, target) {
    const memo = new Map();
    const dp = (i, t, prevC) => {
        if (t < 0) return Infinity;
        if (i === m) return t === 0 ? 0 : Infinity;
        const key = `${i},${t},${prevC}`;
        if (memo.has(key)) return memo.get(key);
        let ans = Infinity;
        if (houses[i] !== 0) {
            const c = houses[i];
            ans = dp(i + 1, t - (c !== prevC ? 1 : 0), c);
        } else {
            for (let c = 1; c <= n; c++) {
                ans = Math.min(ans, cost[i][c - 1] + dp(i + 1, t - (c !== prevC ? 1 : 0), c));
            }
        }
        memo.set(key, ans);
        return ans;
    };
    const res = dp(0, target, 0);
    return res === Infinity ? -1 : res;
};
